content.text:
{
  "pipeline_id": "nanobody-discovery",
  "name": "Nanobody (VHH) Discovery Pipeline",
  "description": "End-to-end VHH nanobody discovery. Step 1 generates candidates with RFdiffusion3 by holding a real VHH framework fixed and diffusing only CDR1/CDR2/CDR3 against the epitope, then designs sequences with ProteinMPNN and predicts each with RoseTTAFold3; step 2 co-folds every candidate with the antigen using Boltz-2 and ranks them by interface confidence. Because FR1-FR4 are preserved, the designs are nanobodies rather than generic binders of nanobody length. Requires a vhhScaffold to build on — there is no default, since the framework determines developability and immunogenicity. NOTE: no numeric dG or Kd is produced — Boltz-2 scores affinity only for small-molecule binders, not protein-protein interfaces; ipTM is the binding signal here. Nanobodies offer advantages over conventional antibodies: smaller size, better tissue penetration, single-domain stability, and ease of production.",
  "estimated_duration": "40-90 minutes",
  "inputs": [
    {
      "name": "targetAntigen",
      "type": "string",
      "required": true,
      "description": "Antigen target: PDB ID (e.g. 1DPX) or workspace file path (e.g. @structures/antigen.pdb)"
    },
    {
      "name": "vhhScaffold",
      "type": "string",
      "required": true,
      "description": "VHH framework to build on: PDB ID (e.g. 1MEL for cAb-Lys3) or workspace file path. Its CDRs are replaced; only FR1-FR4 are kept. Required — no default, because the framework is a developability decision."
    },
    {
      "name": "epitopeResidues",
      "type": "string",
      "required": true,
      "description": "Optional but recommended: epitope residue positions on the antigen, used as RFdiffusion3 hotspots (e.g. '35,52,62,101'). Without them the binding site is not steered."
    },
    {
      "name": "cdrH3Length",
      "type": "string",
      "required": false,
      "default": "",
      "description": "CDR3 length in residues: a number (15) or a range (12-18). Defaults to the scaffold's native CDR3 length. VHH CDR3s are long — 12-24 is typical."
    },
    {
      "name": "numDesigns",
      "type": "string",
      "required": false,
      "default": "5",
      "description": "Number of nanobody candidates to generate (1-10)"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "nanobody-scaffold-design",
      "description": "Generate VHH candidates with RFdiffusion3: FR1-FR4 held fixed from the scaffold, CDR1/CDR2/CDR3 diffused against the epitope hotspots, then ProteinMPNN sequences and RoseTTAFold3 validation"
    },
    {
      "step": 2,
      "tool": "binding-affinity-prediction",
      "description": "Co-fold each designed nanobody with the antigen using Boltz-2 and score the interface — returns ipTM, pTM and pLDDT for ranking (no dG/Kd: Boltz-2 affinity requires a ligand binder)",
      "after": [
        "step1_design_nanobody"
      ]
    }
  ]
}

